(()=>{'use strict';const form=document.getElementById('fashion-jarvis-form');if(!form)return;const status=document.getElementById('fashion-jarvis-status'),output=document.getElementById('fashion-jarvis-answer'),button=form.querySelector('button[type=submit]'),check=document.getElementById('fashion-jarvis-check');let ready=false,busy=false;
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};async function connection(){try{const r=await fetch('/api/jarvis/status');const d=await r.json();if(!r.ok)throw Error('Connection status unavailable');ready=d.ready===true;status.textContent=ready?'Jarvis AI connected. Review every recommendation before acting.':!d.owner?'Jarvis is available to the website owner account.':'Jarvis AI needs its private API connection. Your saved-record planner remains available.';button.disabled=!ready||busy;}catch(e){ready=false;button.disabled=true;status.textContent=e.message;}}
check.onclick=connection;form.onsubmit=async event=>{event.preventDefault();if(!ready||busy)return;const prompt=form.elements.namedItem('prompt').value.trim();if(!prompt)return;busy=true;button.disabled=true;check.disabled=true;output.replaceChildren();status.textContent='Jarvis is preparing a draft…';try{let tasks=[];if(form.elements.namedItem('context').checked){let work={};try{work=JSON.parse(localStorage.getItem('zuxuru-designer-work-v1'))||{};}catch{}const map={sales:'sales',marketing:'marketing',branding:'branding',visibility:'visibility_seo',products:'products',opportunities:'opportunities',skills:'ai_skills',career:'career'};tasks=(work.tasks||[]).filter(t=>!t.done).slice(0,12).map(t=>({module:map[t.area]||'opportunities',title:t.title,deliverable:t.deliverable,done:false}));}const r=await fetch('/api/jarvis/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt,mode:form.elements.namedItem('mode').value,tasks}),signal:AbortSignal.timeout(65000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Jarvis request failed');output.append(el('p',d.answer));for(const source of d.sources||[]){try{const u=new URL(source.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)continue;const a=el('a',source.title||u.hostname);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';const p=el('p');p.append(a);output.append(p);}catch{}}const map={visibility_seo:'visibility',ai_skills:'skills',career:'career'};for(const t of d.tasks||[]){const card=el('article');card.className='record';card.append(el('h3',t.title),el('p',t.deliverable));const review=el('button','Review task');review.type='button';review.onclick=()=>{const f=document.getElementById('designer-task-form');if(['title','deliverable','due'].some(k=>f.elements.namedItem(k).value)&&!confirm('Replace the unsaved task brief?'))return;delete f.dataset.sourceOrderId;f.elements.namedItem('area').value=map[t.module]||t.module;f.elements.namedItem('title').value=String(t.title).slice(0,200);f.elements.namedItem('deliverable').value=String(t.deliverable||'').slice(0,1000);f.elements.namedItem('due').value='';location.hash='my-work';f.scrollIntoView({behavior:'auto'});f.elements.namedItem('title').focus();};card.append(review);output.append(card);}status.textContent='AI draft ready for review. No task was saved and no external action was taken.';}catch(e){status.textContent=e.name==='TimeoutError'?'Jarvis timed out. Retry with a shorter request.':e.message;}finally{busy=false;check.disabled=false;button.disabled=!ready;}};connection();})();
